CREATE OR REPLACE VIEW VW_RISK_EXPOSURE AS
SELECT r.CUSTOMER_ID, r.EXPOSURE_AMT, r.RATING, k.KYC_SCORE, c.REGION FROM DW.RISK_EXPOSURE r JOIN DW.KYC_STATUS k ON r.CUSTOMER_ID = k.CUSTOMER_ID JOIN DW.CUSTOMER_DIM c ON r.CUSTOMER_ID = c.CUSTOMER_ID WHERE r.RUN_DATE = (SELECT MAX(RUN_DATE) FROM DW.RISK_EXPOSURE);
